// Serial: about 2 s. The second request waits for the first.
async function loadSlow(api) {
  const profile = await api.profile();
  const progress = await api.progress();
  return { profile, progress };
}

// Concurrent: about 1 s. Both start, then we wait for both.
async function loadDashboard(api) {
  const profilePromise = api.profile();      // started.
  const progressPromise = api.progress();    // started.
  try {
    const [profile, progress] = await Promise.all([profilePromise, progressPromise]);
    return { profile, progress };
  } catch (error) {
    showMessage("Couldn't load your dashboard. Try again.");
    throw error;                             // let the caller know too.
  }
}
```

| Need | Write |
|---|---|
| B needs A's result. | `const a = await A(); await B(a);` (serial on purpose). |
| A and B independent. | start both, then `await Promise.all([a, b])`. |
| want every result, even failures. | `await Promise.allSettled([...])`. |
| handle a rejection. | `try { await ... } catch (e) { ... }`. |

